/// Outlines of the clickable objects, traced on the art in its 2000x1116 coordinate space.
/// The props are not pixel-identical between scenes: morning and night share a drawing, day and sunset have their own.
/// The cat differs in every scene.
struct Props {
    var clock: [CGPoint], mug: [CGPoint], noteLeft: [CGPoint], noteRight: [CGPoint], record: [CGPoint]
    /// The dark LCD glass of the desk clock: top-left, top-right, bottom-right, bottom-left.
    var lcd: [CGPoint]
    /// Vinyl and label of the record player as ellipses: center, semi-axes, tilt in degrees.
    var vinyl: (center: CGPoint, a: CGFloat, b: CGFloat, tilt: CGFloat), label: (center: CGPoint, a: CGFloat, b: CGFloat, tilt: CGFloat)
    /// Tonearm, redrawn from the art above the spinning sheen so it does not spin.
    var tonearm: [CGPoint]

    static func pts(_ s: String) -> [CGPoint] {
        let v = s.split(separator: ",").map { CGFloat(Double($0)!) }
        return stride(from: 0, to: v.count, by: 2).map { CGPoint(x: v[$0], y: v[$0 + 1]) }
    }

